/**
 * AiGenerateBand — the AI Generate-draft band atop the article editor (Epic
 * #266 v2). This is the ONE licensed cog-ai gradient surface in Range Baseline
 * (design.md §16 backgroundImage; the designer licensed it for this band): a
 * cog-ai gradient with white text + an "AI · Generate draft" eyebrow.
 *
 * Controls: a prompt textarea, a Short/Medium/Long segmented length control
 * (aria-pressed), a Neutral/Urgent/Formal/Casual tone select, and a Generate
 * CTA. On Generate it calls the stateless generate endpoint and hands the
 * returned {headline, author, content} to `onDraft` — the parent populates its
 * editable fields (no persistence here). Success and failure are announced via
 * the shared toast host (success/danger) rather than an inline live region.
 */

import { type ReactElement, useState } from "react";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";
import { useToast } from "@omnicore-platform/platform-chrome/toast";
import {
  generateArticle,
  type ArticleLength,
  type ArticleTone,
  type GeneratedArticleDraft,
} from "../../api/baseline";

export interface AiGenerateBandProps {
  readonly exerciseId: string;
  readonly websiteId: string;
  /** Receives the generated draft to populate the editor (not persisted). */
  readonly onDraft: (draft: GeneratedArticleDraft) => void;
}

const LENGTHS: readonly { value: ArticleLength; label: () => string }[] = [
  { value: "short", label: m.range_baseline_ai_length_short },
  { value: "medium", label: m.range_baseline_ai_length_medium },
  { value: "long", label: m.range_baseline_ai_length_long },
];

const TONES: readonly { value: ArticleTone; label: () => string }[] = [
  { value: "neutral", label: m.range_baseline_ai_tone_neutral },
  { value: "urgent", label: m.range_baseline_ai_tone_urgent },
  { value: "formal", label: m.range_baseline_ai_tone_formal },
  { value: "casual", label: m.range_baseline_ai_tone_casual },
];

export function AiGenerateBand({
  exerciseId,
  websiteId,
  onDraft,
}: AiGenerateBandProps): ReactElement {
  const [prompt, setPrompt] = useState("");
  const [length, setLength] = useState<ArticleLength>("medium");
  const [tone, setTone] = useState<ArticleTone>("neutral");
  const [generating, setGenerating] = useState(false);
  const toast = useToast();

  async function handleGenerate(): Promise<void> {
    setGenerating(true);
    try {
      const draft = await generateArticle(exerciseId, {
        website_id: websiteId,
        prompt,
        article_length: length,
        tone,
      });
      onDraft(draft);
      toast.success(m.range_baseline_ai_generated_status());
    } catch {
      toast.danger(m.range_baseline_ai_error());
    } finally {
      setGenerating(false);
    }
  }

  return (
    <section className="flex flex-col gap-cog-3 rounded-lg bg-cog-ai p-cog-4 text-white [text-shadow:0_1px_2px_rgba(0,0,0,0.25)]">
      <p className="text-eyebrow uppercase tracking-wide text-white/90">
        {m.range_baseline_ai_eyebrow()}
      </p>

      <label className="flex flex-col gap-cog-1">
        <span className="text-caption font-medium text-white/90">
          {m.range_baseline_ai_prompt_label()}
        </span>
        <textarea
          value={prompt}
          rows={2}
          onChange={(e) => setPrompt(e.target.value)}
          placeholder={m.range_baseline_ai_prompt_placeholder()}
          className="min-h-input resize-y rounded-md border border-white/30 bg-white/15 px-cog-3 py-cog-2 text-body-md text-white placeholder:text-white/60 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-white"
        />
      </label>

      <div className="flex flex-wrap items-end gap-cog-4">
        <fieldset className="flex flex-col gap-cog-1">
          <legend className="text-caption font-medium text-white/90">
            {m.range_baseline_ai_length_label()}
          </legend>
          <div className="flex gap-cog-1" role="group">
            {LENGTHS.map((opt) => {
              const selected = length === opt.value;
              return (
                <button
                  key={opt.value}
                  type="button"
                  aria-pressed={selected}
                  onClick={() => setLength(opt.value)}
                  className={[
                    "inline-flex min-h-btn-sm items-center rounded-md border px-cog-3 text-body-sm font-medium",
                    "focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-white",
                    selected
                      ? "border-white bg-white text-cog-blue-700"
                      : "border-white/40 bg-white/10 text-white hover:bg-white/20",
                  ].join(" ")}
                >
                  {opt.label()}
                </button>
              );
            })}
          </div>
        </fieldset>

        <label className="flex flex-col gap-cog-1">
          <span className="text-caption font-medium text-white/90">
            {m.range_baseline_ai_tone_label()}
          </span>
          <select
            value={tone}
            onChange={(e) => setTone(e.target.value as ArticleTone)}
            className="min-h-input rounded-md border border-white/40 bg-white/15 px-cog-3 text-body-sm text-white focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-white"
          >
            {TONES.map((opt) => (
              <option
                key={opt.value}
                value={opt.value}
                className="text-cog-text-primary"
              >
                {opt.label()}
              </option>
            ))}
          </select>
        </label>

        <button
          type="button"
          onClick={() => void handleGenerate()}
          disabled={generating}
          aria-busy={generating}
          className="inline-flex min-h-btn items-center rounded-md border border-white bg-white px-cog-4 text-body-sm font-semibold text-cog-blue-700 hover:bg-white/90 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-white disabled:cursor-not-allowed disabled:border-white/40 disabled:bg-white/40 disabled:text-white/80"
        >
          {generating
            ? m.range_baseline_ai_generating()
            : m.range_baseline_ai_generate_cta()}
        </button>
      </div>
    </section>
  );
}


