/**
 * BaselineMasthead — the publication nameplate (Epic #266).
 *
 * Serif name (the one intentional `.font-serif-masthead` voice) in the
 * website's brand color, optional tagline, and a section nav strip. Shared by
 * the create-modal live preview (§1), the participant article list (§3), and
 * the reading view (§4) so all three read as the same outlet.
 *
 * Brand color is per-row CONTENT data rendered inline (allowed — it's content,
 * not a theme token; §7.4). The §7.4 dark-mode guard: if a saved brand color
 * is too dark to clear 4.5:1 on the dark surface (#0F141B), the masthead NAME
 * falls back to cog-text-primary while the brand color stays on the hairline
 * (which is a decorative non-text accent at 3:1). We compute the fallback at
 * render so the same color works in both themes.
 *
 * Section names run long in de-DE — the strip wraps, never truncates.
 */

import { type ReactElement } from "react";
import { contrastRatio } from "../../utils/contrastCheck";

/** Dark surface token value (cog-surface dark) — for the §7.4 contrast guard. */
// design-ratchet-allow: canvas-render
// Masthead dark surface applied as inline style on a canvas-backed
// banner; cannot be a class here.
const DARK_SURFACE_HEX = "#0F141B";
/** WCAG AA for normal text. */
const AA_TEXT = 4.5;

/**
 * Resolve the masthead-name color for a given theme. On dark, if the brand
 * color can't clear 4.5:1 on the dark surface, return null so the caller uses
 * the cog-text-primary token instead (the brand color still rides the hairline).
 */
export function mastheadNameColor(
  brandColor: string,
  isDark: boolean,
): string | null {
  if (!brandColor) return null;
  if (!isDark) return brandColor;
  const ratio = contrastRatio(brandColor, DARK_SURFACE_HEX);
  if (ratio === null || ratio < AA_TEXT) return null;
  return brandColor;
}

export interface BaselineMastheadProps {
  readonly name: string;
  readonly brandColor: string;
  readonly tagline?: string;
  readonly sections?: readonly string[];
  /** Visual size — "lg" for the reader/preview, "sm" for compact contexts. */
  readonly size?: "sm" | "lg";
}

export function BaselineMasthead({
  name,
  brandColor,
  tagline,
  sections,
  size = "lg",
}: BaselineMastheadProps): ReactElement {
  // The brand color is content; the hairline is decorative. The name color uses
  // the light value inline and lets a dark-mode CSS guard swap to the token.
  const nameStyleLight = brandColor ? { color: brandColor } : undefined;
  const darkSafe = mastheadNameColor(brandColor, true) !== null;

  return (
    <header className="border-b border-cog-divider text-start">
      {/* Brand hairline — decorative (aria-hidden), data-driven color. */}
      {brandColor ? (
        <div
          aria-hidden="true"
          className="h-cog-0-5 w-full"
          style={{ backgroundColor: brandColor }}
        />
      ) : null}

      <div className="px-cog-4 py-cog-4">
        <h1
          // Light: inline brand color. Dark: if the color can't clear 4.5:1 we
          // fall back to the primary text token (the `dark:` class wins via CSS
          // specificity only when darkSafe is false).
          className={[
            "font-serif-masthead font-bold leading-tight text-cog-text-primary",
            size === "lg" ? "text-display-lg" : "text-heading-lg",
            darkSafe ? "" : "dark:!text-cog-text-primary",
          ].join(" ")}
          style={nameStyleLight}
        >
          {name}
        </h1>
        {tagline ? (
          <p className="mt-cog-1 text-body-sm italic text-cog-text-tertiary">
            {tagline}
          </p>
        ) : null}
      </div>

      {sections && sections.length > 0 ? (
        <nav
          aria-label={name}
          className="flex flex-wrap gap-cog-3 border-t border-cog-divider px-cog-4 py-cog-2"
        >
          {sections.map((section) => (
            <span
              key={section}
              className="text-label uppercase tracking-wide text-cog-text-secondary"
            >
              {section}
            </span>
          ))}
        </nav>
      ) : null}
    </header>
  );
}

export default BaselineMasthead;


--- frontends/range-mfe/src/components/baseline/BrowserChromeFrame.tsx (72 lines) ---
/**
 * BrowserChromeFrame — the decorative simulated-browser shell (Epic #266).
 *
 * A slim, inert chrome bar (decorative traffic-light dots + a READ-ONLY URL
 * pill showing the publication domain) wrapping its children. It is a diegetic
 * framing device — it tells the participant "you are visiting a website" — and
 * is used by the create-modal live preview AND the participant reading view
 * (§1 modal / §4 Framed Reader in range-baseline-content-directions.md).
 *
 * Interaction honesty: the URL pill is NOT a link and carries no navigation
 * affordance; the whole chrome bar is `aria-hidden` so SR users skip the fake
 * furniture and land on the real masthead + article. The domain is LTR-isolated
 * (`dir="ltr"`) so it reads left-to-right even inside an ar-AE RTL chrome.
 *
 * Tokens: cog-surface-muted chrome bar on a cog-surface body, cog-divider
 * hairline. No raw hex/px in JSX — bare radius (rounded-lg/md) per the repo
 * gotcha.
 */

import { type ReactElement, type ReactNode } from "react";
import { Lock } from "@omnicore-platform/ui/icons";

export interface BrowserChromeFrameProps {
  /** The publication domain shown in the read-only URL pill (e.g. "beacon.news"). */
  readonly domain: string;
  /** The framed content (masthead + article, or the live preview). */
  readonly children: ReactNode;
  /** Optional extra classes for the outer frame. */
  readonly className?: string;
}

export function BrowserChromeFrame({
  domain,
  children,
  className,
}: BrowserChromeFrameProps): ReactElement {
  return (
    <div
      className={[
        "overflow-hidden rounded-lg border border-cog-divider bg-cog-surface shadow-cog-e1",
        className ?? "",
      ].join(" ")}
    >
      {/* Decorative chrome bar — entirely aria-hidden (fake furniture). */}
      <div
        aria-hidden="true"
        className="flex items-center gap-cog-3 border-b border-cog-divider bg-cog-surface-muted px-cog-3 py-cog-2"
      >
        <div className="flex items-center gap-cog-1">
          <span className="size-cog-2-5 rounded-pill bg-cog-border" />
          <span className="size-cog-2-5 rounded-pill bg-cog-border" />
          <span className="size-cog-2-5 rounded-pill bg-cog-border" />
        </div>
        <div className="flex min-w-cog-0 flex-1 items-center gap-cog-2 rounded-md border border-cog-divider bg-cog-surface px-cog-3 py-cog-1">
          {/* lock glyph — decorative; the whole chrome bar is aria-hidden */}
          <Lock aria-hidden="true" className="h-cog-3 w-cog-3 shrink-0 text-cog-text-tertiary" />
          <span
            dir="ltr"
            className="truncate font-mono text-caption text-cog-text-tertiary"
          >
            {domain}
          </span>
        </div>
      </div>

      <div className="bg-cog-surface">{children}</div>
    </div>
  );
}

export default BrowserChromeFrame;


