/**
 * LeanBadge — the editorial-lean chip (Epic #266).
 *
 * Editorial lean is politically coded, so it is ALWAYS communicated by
 * icon + text, never by color or left/right position alone (which would invert
 * under RTL and fail color-blind users) — see range-baseline-content-directions
 * §1A a11y + §8 RTL. The badge is a neutral cog-* pill; the meaning is the
 * label text. A decorative dot precedes the label.
 *
 * Used by BaselineMasthead, WebsiteCard, and the search result row.
 */

import { type ReactElement } from "react";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";
import type { PoliticalLeaning } from "../../api/baseline";

/**
 * The 6 selectable editorial leans, ordered left→right on the spectrum
 * (independent last). Shared by the LeanBadge, the admin filter, and the
 * create-modal lean-chip control so the option set never drifts.
 */
export const LEANS: readonly Exclude<PoliticalLeaning, "">[] = [
  "left",
  "center-left",
  "center",
  "center-right",
  "right",
  "independent",
];

/** Map the proto lean enum to its localized label, or null when unset. */
export function leanLabel(lean: PoliticalLeaning): string | null {
  switch (lean) {
    case "left":
      return m.range_baseline_lean_left();
    case "center-left":
      return m.range_baseline_lean_center_left();
    case "center":
      return m.range_baseline_lean_center();
    case "center-right":
      return m.range_baseline_lean_center_right();
    case "right":
      return m.range_baseline_lean_right();
    case "independent":
      return m.range_baseline_lean_independent();
    default:
      return null;
  }
}

export interface LeanBadgeProps {
  readonly lean: PoliticalLeaning;
}

export function LeanBadge({ lean }: LeanBadgeProps): ReactElement | null {
  const label = leanLabel(lean);
  if (label === null) return null;
  return (
    <span className="inline-flex items-center gap-cog-1 rounded-pill border border-cog-divider bg-cog-surface-muted px-cog-2 py-cog-0-5 text-micro font-semibold uppercase text-cog-text-secondary">
      <span aria-hidden="true" className="size-cog-1-5 rounded-pill bg-cog-border" />
      {label}
    </span>
  );
}

export default LeanBadge;


