    >
      <span
        aria-hidden="true"
        className="size-cog-1-5 rounded-pill bg-cog-success-500 motion-safe:animate-pulse dark:bg-cog-success-dark"
      />
      {m.range_baseline_card_rss_live()}
    </span>
  );
}

/**
 * The admin-only outlet-profile affordance. When supplied (admin variant with a
