                  ? "inline-flex min-h-btn-sm items-center rounded-md border border-cog-divider bg-cog-surface-muted px-cog-3 text-body-sm font-medium text-cog-text-tertiary cursor-not-allowed"
                  : "inline-flex min-h-btn-sm items-center rounded-md border border-cog-border bg-cog-surface px-cog-3 text-body-sm font-medium text-cog-text-secondary hover:bg-cog-surface-muted focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-cog-focus disabled:cursor-not-allowed disabled:border-cog-divider disabled:bg-cog-surface-muted disabled:text-cog-text-tertiary"
              }
