/**
 * WebsiteCreateModal — the New-website dialog (Epic #266, #336).
 *
 * Two-column dialog: Manual form (left) + a live BaselineMasthead /
 * BrowserChromeFrame preview (right). AI-assisted / Import / Hybrid modes are
 * deferred → disabled "Soon" chips. Built incrementally against the
 * test-writer's failing tests; this commit lands the dialog shell + the
 * publication-name field with focus-on-open.
 *
 * Built on @omnicore-platform/ui Dialog (Radix). Dialog.Content owns
 * portalling (the panel mounts at the document root as a fixed overlay — it
 * never sits inline pushing the roster down), the focus trap, focus restore,
 * scroll lock, Esc-to-close, and scrim-click dismissal; Root's onOpenChange
 * routes every dismissal to onClose and vetoes it mid-submit. The dialog's
 * accessible name is sourced by Radix from Dialog.Title; focus moves to the
 * name field on open via onOpenAutoFocus (modal a11y, design.md §1 modal).
 */

import { type ReactElement, useId, useRef, useState } from "react";
import { Dialog, RadioGroup } from "@omnicore-platform/ui";
import { Check, X } from "@omnicore-platform/ui/icons";
import { useToast } from "@omnicore-platform/platform-chrome/toast";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";
import { rangeDomain } from "../../lib/rangeDomain";
import { BaselineMasthead } from "./BaselineMasthead";
import { BrowserChromeFrame } from "./BrowserChromeFrame";
import {
  BASELINE_BRAND_PALETTE,
  DEFAULT_BRAND_COLOR,
} from "../../constants/baselineBrandPalette";
import {
  createWebsite,
  setWebsiteEnabled,
  updateWebsite,
  type BaselineWebsite,
  type PoliticalLeaning,
} from "../../api/baseline";
import { LEANS, leanLabel } from "./LeanBadge";

export interface WebsiteCreateModalProps {
  /**
   * The exercise this dialog operates within. On CREATE the new website is
   * enabled for this exercise (SetWebsiteEnabled) right after it's added to the
   * org catalog — otherwise it would live in the catalog but never appear in the
   * exercise roster, which reads the per-exercise config rows.
   */
  readonly exerciseId: string;
  /** Close the dialog (Cancel / Esc / backdrop / post-create). */
  readonly onClose: () => void;
  /** Called after a successful create/save so the caller can refetch the list. */
  readonly onCreated: () => void;
  /**
   * When present, the dialog opens in EDIT mode: fields prefill from this
   * website, the title/submit reflect editing, and submit PATCHes via
   * UpdateWebsite instead of POSTing a new website.
   */
  readonly website?: BaselineWebsite;
}

export function WebsiteCreateModal({
  exerciseId,
  onClose,
  onCreated,
  website,
}: WebsiteCreateModalProps): ReactElement {
  const isEdit = website !== undefined;
  const nameRef = useRef<HTMLInputElement>(null);
  const [name, setName] = useState(website?.name ?? "");
  // Domain auto-suggests from the name until the user edits it directly; after
  // that the manual value sticks (domainDirty). In edit mode the existing
  // domain is the starting value and is treated as already-dirty (don't
  // re-derive it from the name).
  const [domain, setDomain] = useState(website?.domain_slug ?? "");
  const [domainDirty, setDomainDirty] = useState(isEdit);
  const [tagline, setTagline] = useState(website?.tagline ?? "");
  const [lean, setLean] = useState<PoliticalLeaning>(
    website?.political_leaning ?? "",
  );
  const [brandColor, setBrandColor] = useState(
    website?.primary_color || DEFAULT_BRAND_COLOR,
  );
  const [sections, setSections] = useState<readonly string[]>(
    website?.sections ?? [],
  );
  // Content source: "authored" is the default (no feed — articles are written
  // by hand in the Article Manager); "rss" reveals the RSS-URL field + creates
  // a Live feed. AI-generated "synthetic" + "hybrid" are deferred ("Soon").
  const [source, setSource] = useState<"authored" | "rss">("authored");
  const [feedUrl, setFeedUrl] = useState("");
  const [submitting, setSubmitting] = useState(false);
  const toast = useToast();

  const effectiveDomain = domainDirty ? domain : suggestDomain(name);

  async function handleCreate(): Promise<void> {
    setSubmitting(true);
    try {
      if (website !== undefined) {
        // Edit mode: PATCH the existing website. The content source / RSS URL
        // belong to feed provisioning (create-only), so edit covers the
        // editorial identity fields only. Edit never re-enables for the
        // exercise — the website is already part of the roster.
        await updateWebsite(website.id, {
          name,
          domain_slug: effectiveDomain,
          tagline,
          primary_color: brandColor,
          ...(lean !== "" ? { political_leaning: lean } : {}),
          sections,
        });
      } else {
        // Create mode: add the website to the org catalog, then enable it for
        // this exercise. CreateWebsite has no exercise binding, so without the
        // SetWebsiteEnabled step the new site would never appear in the
        // exercise roster (which reads the per-exercise config rows).
        const { website: created } = await createWebsite({
          name,
          domain_slug: effectiveDomain,
          tagline,
          primary_color: brandColor,
          ...(lean !== "" ? { political_leaning: lean } : {}),
          ...(sections.length > 0 ? { sections } : {}),
          // Authored source creates no live feed → omit feed_url. Live RSS
          // sends the entered URL so the upstream provisions the feed + sync.
          ...(source === "rss" && feedUrl ? { feed_url: feedUrl } : {}),
        });
        await setWebsiteEnabled(exerciseId, created.id, { is_enabled: true });
        // Success feedback is create-only — edit's confirmation is simply the
        // dialog closing on the already-visible roster entry.
        toast.success(m.range_baseline_modal_create_success());
      }
      onCreated();
      onClose();
    } catch {
      // Surface the failure (never silently close); the dialog stays open so
      // the user sees the toast and can retry / cancel. A danger toast
      // (role="alert") from the shared toast host — not an inline element —
      // so it fires from inside this Radix modal without pointer-events
      // fighting the scrim (see toast.tsx's pointerEvents:"auto" viewport).
      toast.danger(m.range_baseline_modal_error());
    } finally {
      setSubmitting(false);
    }
  }

  return (
    // Mounted === open. Radix-driven dismissals (Esc, scrim click) route here;
    // veto them mid-submit, otherwise forward to onClose.
    <Dialog.Root
      open
      onOpenChange={(open) => {
        if (!open && !submitting) onClose();
      }}
    >
      <Dialog.Content
        // Radix would focus the panel itself; redirect the initial focus to
        // the publication-name field (modal a11y, design.md §1 modal).
        onOpenAutoFocus={(e) => {
