        // Wider than the default modal width — the form is two-column with a
        // live preview. Capped to the viewport with internal scroll so a tall
        // form never overflows off-screen.
        className="max-h-cog-vh-inset-96 w-full max-w-cog-modal-w-clamped overflow-y-auto p-cog-6"
      >
        <Dialog.Title asChild>
          <h2 className="font-serif-masthead text-heading-lg font-bold text-cog-text-primary">
            {isEdit
              ? m.range_baseline_modal_edit_title()
              : m.range_baseline_modal_title()}
          </h2>
        </Dialog.Title>

      <ModeChips />

      <div className="mt-cog-4 grid grid-cols-1 gap-cog-5 md:grid-cols-2">
        <div className="flex flex-col gap-cog-4">
        <Field label={m.range_baseline_modal_field_name()}>
          {(id) => (
            <input
              id={id}
              ref={nameRef}
              type="text"
              value={name}
              onChange={(e) => setName(e.target.value)}
              placeholder={m.range_baseline_modal_field_name_placeholder()}
              className={INPUT_CLS}
            />
          )}
        </Field>

        <Field
          label={m.range_baseline_modal_field_domain()}
          hint={m.range_baseline_modal_field_domain_hint()}
        >
          {(id) => (
            <div className="flex items-stretch">
              <input
                id={id}
                type="text"
                dir="ltr"
                value={effectiveDomain}
                onChange={(e) => {
                  setDomainDirty(true);
                  setDomain(e.target.value);
