/**
 * WebsiteMastheadPreview — the idle right-pane content for the Article Manager
 * (Epic #266 v2, Direction 1B). Shown when no article row is selected.
 *
 * Fetches the owning website via useBaselineWebsite and renders:
 *   - Loading: 3 animate-pulse skeleton bars
 *   - Error/forbidden: icon + error copy with a retry button
 *   - Data: masthead band (name, tagline, domain) + "Latest Headlines" eyebrow
 *     + the website's latest_article_title, or the empty hint when absent.
 *
 * The masthead band mirrors the same design voice as BaselineMasthead (serif
 * name, italic tagline, monospace domain) but as a leaner preview — no hairline,
 * no section nav — because this is an instructor preview, not the participant
 * reader. The brand color is applied as an inline style (content-driven, not a
 * theme token, per §7.4).
 *
 * a11y: heading hierarchy — the publication name is h2 (the page h1 is the
 * "Manage Articles" heading in the route chrome). No interactive elements; focus
 * does not move on mount (only +New moves focus per the spec).
 */

import { type ReactElement } from "react";
import { CircleAlert } from "@omnicore-platform/ui/icons";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";
import { useBaselineWebsite } from "../../hooks/useBaselineWebsite";

export interface WebsiteMastheadPreviewProps {
  readonly websiteId: string;
  readonly exerciseId: string;
}

export function WebsiteMastheadPreview({
  websiteId,
}: WebsiteMastheadPreviewProps): ReactElement {
  const state = useBaselineWebsite(websiteId);

  if (state.state === "loading") {
    return <MastheadSkeleton />;
  }

  if (state.state === "error" || state.state === "forbidden") {
    // The right pane shows a non-interactive error hint only — no retry button
    // (the left pane's articles error owns the retry affordance when articles
    // also fail; avoid ambiguous duplicate "Retry" buttons on the same screen).
    return (
      <div className="flex flex-col items-center gap-cog-3 py-cog-8 text-center">
        <AlertCircleIcon />
        <p className="text-body-sm text-cog-text-secondary">
          {m.range_baseline_articles_error({ retry: "" })}
        </p>
      </div>
    );
  }

  const { website } = state;
  const hasHeadline =
    typeof website.latest_article_title === "string" &&
    website.latest_article_title.length > 0;

  return (
    <div className="flex flex-col gap-cog-3">
      {/* Masthead band — publication name, tagline, domain. */}
      <div className="flex flex-col gap-cog-1 border-b-2 border-cog-text-primary pb-cog-3">
        <h2
          className="font-serif-masthead text-heading-lg font-bold text-cog-text-primary"
          style={
            website.primary_color
              ? { color: website.primary_color }
              : undefined
          }
        >
          {website.name}
        </h2>
        {website.tagline ? (
          <p className="text-body-sm italic text-cog-text-secondary">
            {website.tagline}
          </p>
        ) : null}
        {website.real_url ? (
          <p
            dir="ltr"
            className="font-mono text-caption text-cog-text-tertiary"
          >
            {domainFromUrl(website.real_url)}
          </p>
        ) : null}
      </div>

      {/* Latest Headlines section — only shown when there is at least one. */}
      {hasHeadline ? (
        <div className="flex flex-col gap-cog-2">
          <p className="text-eyebrow uppercase text-cog-text-eyebrow">
            {m.range_baseline_website_preview_headlines_label()}
          </p>
          <ul className="flex flex-col gap-cog-1">
            <li className="text-body-sm text-cog-text-primary">
              {website.latest_article_title}
            </li>
          </ul>
        </div>
      ) : (
        /* Empty hint — when the website has no articles yet. */
        <p className="text-center text-body-sm text-cog-text-secondary">
          {m.range_baseline_website_preview_empty_hint()}
        </p>
      )}
    </div>
  );
}

/** Extract the hostname from a URL string; falls back to the raw string. */
function domainFromUrl(url: string): string {
  try {
    return new URL(url).hostname;
  } catch {
    return url;
  }
}

/** Three pulsing skeleton bars for the loading state. */
function MastheadSkeleton(): ReactElement {
  return (
    <div className="flex flex-col gap-cog-3 animate-pulse" aria-busy="true">
      <div className="h-cog-5-5 w-3/4 rounded-md bg-cog-surface-muted" />
      <div className="h-cog-4 w-1/2 rounded-md bg-cog-surface-muted" />
      <div className="h-cog-4 w-2/3 rounded-md bg-cog-surface-muted" />
    </div>
  );
}

