/**
 * tileTreatment.ts — the WebsiteCard avatar-tile ink/ring decision (#2196).
 *
 * The avatar tile's background is arbitrary content data (`primary_color`),
 * painted behind a hardcoded `text-white` monogram. A near-white brand color
 * paints a white monogram on a white tile — invisible — and a near-white tile
 * has no visible edge against the white `cog-surface` card behind it. This
 * module is the pure decision: given the tile's background hex, does the
 * monogram need dark ink, and does the tile need a hairline ring to stay
 * visible against the card surface.
 *
 * The threshold is 3:1, NOT the 4.5:1 WCAG AA text bar. The monogram is
 * `aria-hidden` decorative — the accessible name of the outlet is its heading
 * text, not the tile — so the bar here is legibility, not AA text compliance.
 * 3:1 matches contrastCheck.ts's own non-text / UI-component bar (WCAG 2.2
 * §1.4.11), which is the right family of requirement for a decorative
 * graphical tile.
 *
 * Measured against the seeded catalog (services/range-svc/src/range_svc/
 * baseline_seed/catalog.py), the choice of bar changes the outcome for exactly
 * two outlets: TechCrunch #0A9E01 (3.56:1 white-on) and Associated Press
 * #FF322E (3.65:1) keep white ink at 3:1 and would flip to dark ink at 4.5:1.
 * Only the two oranges — Al Jazeera #FA9000 (2.32:1) and Reuters #FF8000
 * (2.52:1) — take dark ink either way. Every other seeded color, #E60000
 * included at 4.81:1, is unaffected by the threshold.
 *
 * Reuses `contrastRatio` from ../../utils/contrastCheck rather than
 * reimplementing color math. Deliberately NOT `isWcagAA`, which shares the
 * 3:1 bar but collapses unparseable input to `false` — here that must fall
 * back to today's white-ink look, not to dark ink plus a ring.
 */

import { contrastRatio } from "../../utils/contrastCheck";

/** The decorative-legibility bar (see module doc comment for why not 4.5). */
const MIN_CONTRAST = 3;

export interface TileTreatment {
  /** Tailwind text-colour class for the tile's monogram. */
  readonly inkClass: "text-white" | "text-cog-text-primary";
  /** True when the tile background is light enough to need a hairline ring. */
  readonly needsRing: boolean;
}

/** The tile's default look: white monogram, no ring. Also the unparseable-hex fallback. */
const WHITE_INK: TileTreatment = { inkClass: "text-white", needsRing: false };

/** Dark monogram plus a hairline ring, for backgrounds too light for white ink. */
const DARK_INK_WITH_RING: TileTreatment = {
  inkClass: "text-cog-text-primary",
  needsRing: true,
};

/**
 * Decide the avatar tile's monogram ink color and whether it needs a hairline
 * ring, from the tile's background hex. See module doc comment for the 3:1
 * threshold rationale and the fallback for unparseable input.
 */
// design-ratchet-allow: canvas-render
// Reference white for the contrast computation below — contrastRatio (see
// BaselineMasthead's identical DARK_SURFACE_HEX) takes a plain hex STRING,
// not a utility class, so this can't be a cog-* token.
const WHITE_HEX = "#FFFFFF";

export function tileTreatment(brandHex: string): TileTreatment {
  const ratio = contrastRatio(WHITE_HEX, brandHex);
  // Unparseable input keeps today's shipped look rather than flipping to dark ink.
  if (ratio === null) return WHITE_INK;
  return ratio >= MIN_CONTRAST ? WHITE_INK : DARK_INK_WITH_RING;
}



