/**
 * ArticleEditorForm — the editable form for an authored article (Epic #266 v2,
 * Article Manager). Renders an AI Generate-draft band on top (the single
 * licensed cog-ai gradient surface) and the editable fields below: headline,
 * author, body, image URL, plus Breaking / Featured toggles. Saving creates or
 * patches via the article endpoints; the AI band populates the fields without
 * persisting.
 *
 * The form owns local field state seeded from the article. The route remounts
 * it (via React key) when the selection changes, so the seed is the source of
 * truth per-selection — no derived-state syncing needed.
 */

import {
  type ReactElement,
  type ReactNode,
  useId,
  useState,
} from "react";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";
import { useToast } from "@omnicore-platform/platform-chrome/toast";
import {
  createArticle,
  updateArticle,
  type ArticleLength,
  type ArticleTone,
  type BaselineArticle,
} from "../../api/baseline";
import { AiGenerateBand } from "./AiGenerateBand";

export interface ArticleEditorFormProps {
  readonly exerciseId: string;
  readonly websiteId: string;
  /** The article being edited, or null for a brand-new draft. */
  readonly article: BaselineArticle | null;
  /** Called after a successful create/save so the caller can refetch. */
  readonly onSaved: () => void;
  /** Cancel — discard and return to the empty/select state. */
  readonly onCancel: () => void;
  /**
   * Delete this article (soft). Only offered when editing an existing article
   * (never on a new draft). The caller owns the confirm + refetch.
   */
  readonly onDelete?: () => void;
}

export function ArticleEditorForm({
  exerciseId,
  websiteId,
  article,
  onSaved,
  onCancel,
  onDelete,
}: ArticleEditorFormProps): ReactElement {
  const [title, setTitle] = useState(article?.title ?? "");
  const [author, setAuthor] = useState(
    article?.author || m.range_baseline_article_author_default(),
  );
  const [body, setBody] = useState(article?.content ?? "");
  const [imageUrl, setImageUrl] = useState(article?.image_url ?? "");
  const [isBreaking, setIsBreaking] = useState(article?.is_breaking ?? false);
  const [isFeatured, setIsFeatured] = useState(article?.is_featured ?? false);
  const [submitting, setSubmitting] = useState(false);
  const toast = useToast();

  async function handleSave(): Promise<void> {
    setSubmitting(true);
    try {
      if (article !== null) {
        await updateArticle(article.id, {
          exercise_id: exerciseId,
          title,
          content: body,
          author,
          image_url: imageUrl,
          is_breaking: isBreaking,
          is_featured: isFeatured,
        });
      } else {
        await createArticle(exerciseId, {
          website_id: websiteId,
          title,
          content: body,
          author,
          image_url: imageUrl,
          is_breaking: isBreaking,
          is_featured: isFeatured,
        });
      }
      onSaved();
    } catch {
      toast.danger(m.range_baseline_article_save_error());
    } finally {
      setSubmitting(false);
    }
  }

  return (
    <div className="flex flex-col gap-cog-5">
      <AiGenerateBand
        exerciseId={exerciseId}
        websiteId={websiteId}
        onDraft={(draft) => {
          // The AI draft populates the editable fields in place — never persisted
          // here. The instructor reviews, then Saves (which calls Create).
          setTitle(draft.headline);
          setAuthor(draft.author || m.range_baseline_article_author_default());
          setBody(draft.content);
        }}
      />

      <Field label={m.range_baseline_article_field_title()}>
        {(id) => (
          <input
            id={id}
            type="text"
            value={title}
            onChange={(e) => setTitle(e.target.value)}
            className={INPUT_CLS}
          />
        )}
      </Field>

      <Field label={m.range_baseline_article_field_author()}>
        {(id) => (
          <input
            id={id}
            type="text"
            value={author}
            onChange={(e) => setAuthor(e.target.value)}
            className={INPUT_CLS}
          />
        )}
      </Field>

      <Field label={m.range_baseline_article_field_body()}>
        {(id) => (
          <textarea
            id={id}
            value={body}
            rows={8}
            onChange={(e) => setBody(e.target.value)}
            // body-md (14) for CJK legibility (design note).
            className={`${INPUT_CLS} min-h-input resize-y py-cog-2 text-body-md`}
          />
        )}
      </Field>

      <Field label={m.range_baseline_article_field_image()}>
        {(id) => (
          <input
            id={id}
            type="text"
            dir="ltr"
            value={imageUrl}
            onChange={(e) => setImageUrl(e.target.value)}
            className={`${INPUT_CLS} font-mono`}
          />
        )}
      </Field>

      <div className="flex flex-wrap gap-cog-4">
        <ToggleSwitch
          label={m.range_baseline_article_toggle_breaking()}
          checked={isBreaking}
          onChange={setIsBreaking}
        />
        <ToggleSwitch
          label={m.range_baseline_article_toggle_featured()}
          checked={isFeatured}
          onChange={setIsFeatured}
        />
      </div>

      <div className="flex items-center justify-between gap-cog-2 border-t border-cog-divider pt-cog-4">
        {/* Delete sits apart (destructive) — only for an existing article. */}
        {onDelete !== undefined ? (
          <button
            type="button"
            onClick={onDelete}
            className="inline-flex min-h-btn items-center rounded-md border border-cog-danger-300 bg-cog-danger-50 px-cog-4 text-body-sm font-medium text-cog-danger-500 hover:bg-cog-danger-200 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-cog-focus dark:border-cog-danger-dark-border dark:bg-cog-danger-dark-bg dark:text-cog-danger-dark"
          >
            {m.range_baseline_article_delete()}
          </button>
        ) : (
          <span />
        )}
        <div className="flex items-center gap-cog-2">
        <button
          type="button"
          onClick={onCancel}
          className="inline-flex min-h-btn items-center rounded-md border border-cog-border bg-cog-surface px-cog-4 text-body-sm font-medium text-cog-text-secondary hover:bg-cog-surface-muted focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-cog-focus"
        >
          {m.range_baseline_article_cancel()}
        </button>
        <button
          type="button"
          onClick={() => void handleSave()}
          disabled={submitting}
          aria-busy={submitting}
          className="inline-flex min-h-btn items-center rounded-md bg-cog-blue-600 px-cog-4 text-body-sm font-semibold text-white hover:bg-cog-blue-700 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-cog-focus disabled:cursor-not-allowed disabled:bg-cog-surface-muted disabled:text-cog-text-tertiary dark:bg-cog-blue-700 dark:hover:bg-cog-blue-800"
        >
          {submitting
            ? m.range_baseline_article_saving()
            : m.range_baseline_article_save()}
        </button>
        </div>
      </div>
    </div>
  );
}

/** A role="switch" toggle with explicit On/Off text (never icon/color alone). */
function ToggleSwitch({
  label,
  checked,
  onChange,
}: {
  label: string;
  checked: boolean;
  onChange: (next: boolean) => void;
}): ReactElement {
  return (
    <button
      type="button"
      role="switch"
      aria-checked={checked}
      aria-label={label}
      onClick={() => onChange(!checked)}
      className={[
        "inline-flex min-h-btn-sm items-center gap-cog-2 rounded-md border px-cog-3 text-body-sm font-medium",
        "focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-cog-focus",
        checked
          ? "border-cog-blue-600 bg-cog-blue-50 text-cog-blue-700 dark:border-cog-blue-300 dark:bg-cog-blue-800 dark:text-cog-blue-100"
          : "border-cog-border-emphasized bg-cog-surface text-cog-text-secondary hover:bg-cog-surface-muted",
      ].join(" ")}
    >
      <span
        aria-hidden="true"
        className={[
          "size-cog-2 rounded-pill",
          checked
            ? "bg-cog-blue-600 dark:bg-cog-blue-300"
            : "bg-cog-border-emphasized",
        ].join(" ")}
      />
      {label}
      <span className="text-cog-text-tertiary">
        {checked
          ? m.range_baseline_article_toggle_on()
          : m.range_baseline_article_toggle_off()}
      </span>
    </button>
  );
}

/** Shared input class — single source for the editor's text fields. */
const INPUT_CLS =
  "min-h-input rounded-md border border-cog-border bg-cog-surface px-cog-3 text-body-sm text-cog-text-primary placeholder:text-cog-text-tertiary focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-cog-focus";

/** A labeled input wrapper with a real <label htmlFor> association. */
function Field({
  label,
  children,
}: {
  label: string;
  children: (id: string) => ReactNode;
}): ReactElement {
  const id = useId();
  return (
    <div className="flex flex-col gap-cog-1">
      <label
        htmlFor={id}
        className="text-caption font-medium text-cog-text-secondary"
      >
        {label}
      </label>
      {children(id)}
    </div>
  );
}

// Re-export for the route to reference the article-length / tone unions without
// a separate import path.
export type { ArticleLength, ArticleTone };


