/**
 * BrowserChromeFrame — the decorative simulated-browser shell (Epic #266).
 *
 * A slim, inert chrome bar (decorative traffic-light dots + a READ-ONLY URL
 * pill showing the publication domain) wrapping its children. It is a diegetic
 * framing device — it tells the participant "you are visiting a website" — and
 * is used by the create-modal live preview AND the participant reading view
 * (§1 modal / §4 Framed Reader in range-baseline-content-directions.md).
 *
 * Interaction honesty: the URL pill is NOT a link and carries no navigation
 * affordance; the whole chrome bar is `aria-hidden` so SR users skip the fake
 * furniture and land on the real masthead + article. The domain is LTR-isolated
 * (`dir="ltr"`) so it reads left-to-right even inside an ar-AE RTL chrome.
 *
 * Tokens: cog-surface-muted chrome bar on a cog-surface body, cog-divider
 * hairline. No raw hex/px in JSX — bare radius (rounded-lg/md) per the repo
 * gotcha.
 */

import { type ReactElement, type ReactNode } from "react";
import { Lock } from "@omnicore-platform/ui/icons";

export interface BrowserChromeFrameProps {
  /** The publication domain shown in the read-only URL pill (e.g. "beacon.news"). */
  readonly domain: string;
  /** The framed content (masthead + article, or the live preview). */
  readonly children: ReactNode;
  /** Optional extra classes for the outer frame. */
  readonly className?: string;
}

export function BrowserChromeFrame({
  domain,
  children,
  className,
}: BrowserChromeFrameProps): ReactElement {
  return (
    <div
      className={[
        "overflow-hidden rounded-lg border border-cog-divider bg-cog-surface shadow-cog-e1",
        className ?? "",
      ].join(" ")}
    >
      {/* Decorative chrome bar — entirely aria-hidden (fake furniture). */}
      <div
        aria-hidden="true"
        className="flex items-center gap-cog-3 border-b border-cog-divider bg-cog-surface-muted px-cog-3 py-cog-2"
      >
        <div className="flex items-center gap-cog-1">
          <span className="size-cog-2-5 rounded-pill bg-cog-border" />
          <span className="size-cog-2-5 rounded-pill bg-cog-border" />
          <span className="size-cog-2-5 rounded-pill bg-cog-border" />
        </div>
        <div className="flex min-w-cog-0 flex-1 items-center gap-cog-2 rounded-md border border-cog-divider bg-cog-surface px-cog-3 py-cog-1">
          {/* lock glyph — decorative; the whole chrome bar is aria-hidden */}
          <Lock aria-hidden="true" className="h-cog-3 w-cog-3 shrink-0 text-cog-text-tertiary" />
          <span
            dir="ltr"
            className="truncate font-mono text-caption text-cog-text-tertiary"
          >
            {domain}
          </span>
        </div>
      </div>

      <div className="bg-cog-surface">{children}</div>
    </div>
  );
}

export default BrowserChromeFrame;


