/**
 * SyncToast — a fixed-position, portal-rendered toast for the force-sync
 * outcome (Epic #266). No shared platform-chrome toast exists, so this is a
 * small self-contained one.
 *
 * The earlier feedback was an inline banner near the top of the admin page, so
 * syncing a card lower in the list scrolled the confirmation out of view. This
 * renders into a `position:fixed` region anchored to the bottom-end corner via
 * a portal to `document.body`, so it stays visible regardless of scroll.
 *
 *  - queued  → polite role="status" + aria-live="polite" confirmation.
 *  - error   → assertive role="alert" + aria-live="assertive" alert.
 *
 * Icon + text (never color alone), cog-* tokens, dark-mode + RTL-clean (logical
 * `end`/`bottom` placement), and an explicit Dismiss control. The auto-dismiss
 * timer is owned by the parent route (it predates this component); this is
 * presentation only.
 */

import { type ReactElement } from "react";
import { createPortal } from "react-dom";
import { RefreshCw, TriangleAlert } from "@omnicore-platform/ui/icons";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";

export interface SyncToastProps {
  readonly kind: "queued" | "error";
  readonly onDismiss: () => void;
}

export function SyncToast({ kind, onDismiss }: SyncToastProps): ReactElement {
  const queued = kind === "queued";
  return createPortal(
    <div
      // Fixed to the bottom-end corner so it never scrolls away. Logical
      // inset (`end`/`bottom`) keeps the corner correct under RTL chrome.
      data-baseline-sync-toast=""
      className="fixed bottom-cog-4 end-cog-4 z-50 max-w-sm"
    >
      <div
        role={queued ? "status" : "alert"}
        aria-live={queued ? "polite" : "assertive"}
        className={[
          "flex items-start gap-cog-2 rounded-lg border px-cog-3 py-cog-2 text-body-sm shadow-cog-e2",
          queued
            ? "border-cog-success-200 bg-cog-success-50 text-cog-text-primary dark:border-cog-success-dark-border dark:bg-cog-success-dark-bg"
            : "border-cog-danger-300 bg-cog-danger-50 text-cog-text-primary dark:border-cog-danger-dark-border dark:bg-cog-danger-dark-bg",
        ].join(" ")}
      >
        {queued ? <SyncIcon /> : <AlertIcon />}
        <span className="flex-1">
          {queued
            ? m.range_baseline_admin_sync_queued()
            : m.range_baseline_admin_sync_error()}
        </span>
        <button
          type="button"
          onClick={onDismiss}
          aria-label={m.range_error_toast_action_dismiss()}
          className="ms-cog-1 inline-flex min-h-btn-sm min-w-btn-sm items-center justify-center rounded-md px-cog-1 text-cog-text-secondary hover:bg-cog-surface-muted focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-cog-focus"
        >
          {m.range_error_toast_action_dismiss()}
        </button>
      </div>
    </div>,
    document.body,
  );
}

/** A small sync/refresh glyph for the queued toast (decorative). */
function SyncIcon(): ReactElement {
  return (
    <RefreshCw
      aria-hidden="true"
      className="mt-cog-0-5 h-cog-4 w-cog-4 shrink-0 text-cog-success-500 dark:text-cog-success-dark"
    />
  );
}

/** A small alert glyph for the error toast (decorative; text carries it). */
function AlertIcon(): ReactElement {
  return (
    <TriangleAlert
      aria-hidden="true"
      className="mt-cog-0-5 h-cog-4 w-cog-4 shrink-0 text-cog-danger-500 dark:text-cog-danger-dark"
    />
  );
}


