/**
 * WebsiteCard — the Direction 1B "Editorial Card" (Epic #266).
 *
 * A platform-chrome card given a press-masthead identity: the publication name
 * in the serif masthead voice, a monospace domain, lean + RSS-live +
 * article-count badges, the latest-article mini-preview (serif headline), and
 * a footer.
 *
 *  - admin variant   → footer carries the per-exercise enable Toggle + Sync +
 *                       Settings (used by WebsitesAdminRoute).
 *  - participant variant → the whole card is a single Link to the article list
 *                       (used by the participant browser, §2A).
 *
 * The card vocabulary is shared so admin + participant read as the same outlet.
 * Brand color is per-row content data carried by the avatar tile alone: the
 * tile's `style` background is the raw brand hex, and `tileTreatment` (#2196)
 * derives the monogram's ink color and an optional hairline ring from that
 * hex's luminance, so a near-white brand color doesn't paint an invisible
 * white-on-white monogram. Lean meaning is the badge, never a color (§1B
 * a11y). Monospace domain is LTR-isolated. cog-* tokens; bare radius;
 * dark-mode + RTL clean.
 */

import { type ReactElement, type ReactNode } from "react";
import { Link } from "react-router-dom";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";
import type { BaselineWebsite } from "../../api/baseline";
import { rangeDomain } from "../../lib/rangeDomain";
import { DEFAULT_BRAND_COLOR } from "../../constants/baselineBrandPalette";
import { useGatedAffordance } from "../../hooks/useGatedAffordance";
import { tileTreatment } from "./tileTreatment";
import { LeanBadge } from "./LeanBadge";
import { VerifiedBadge } from "../VerifiedBadge";

/** A monogram from the publication name for the avatar chip. */
function monogram(name: string): string {
  const trimmed = name.trim();
  if (trimmed === "") return "?";
  const parts = trimmed.split(/\s+/);
  if (parts.length === 1) return parts[0].slice(0, 1).toUpperCase();
  return (parts[0][0] + parts[parts.length - 1][0]).toUpperCase();
}

/** RSS-live pulse dot — static when prefers-reduced-motion (§6). */
function RssLiveBadge(): ReactElement {
  return (
    <span
      role="status"
      className="inline-flex items-center gap-cog-1 rounded-pill border border-cog-success-200 bg-cog-success-50 px-cog-2 py-cog-0-5 text-micro font-semibold uppercase text-cog-success-500 dark:border-cog-success-dark-border dark:bg-cog-success-dark-bg dark:text-cog-success-dark"
    >
      <span
        aria-hidden="true"
        className="size-cog-1-5 rounded-pill bg-cog-success-500 motion-safe:animate-pulse dark:bg-cog-success-dark"
      />
      {m.range_baseline_card_rss_live()}
    </span>
  );
}

/**
 * The admin-only outlet-profile affordance. When supplied (admin variant with a
 * profiled website), the badge row renders a verified `@handle` pill linking to
 * the outlet Character's profile-detail page. Participant cards never supply
 * this — routing a participant to an instructor profile surface is a leak.
 */
interface OutletProfileLink {
  readonly exerciseId: string;
  readonly characterId: string;
  readonly username: string;
}

interface WebsiteCardChromeProps {
  readonly website: BaselineWebsite;
  readonly hasLiveFeed: boolean;
  readonly articleCount: number;
  readonly latestHeadline?: string;
  readonly footer?: ReactNode;
  /** Admin-only verified outlet-profile pill target. Omitted → no pill. */
  readonly outletProfile?: OutletProfileLink;
}

/**
 * The shared visual body — masthead identity + badges + latest-story preview.
 * Both variants render this; only the footer / outer wrapper differ.
 */
function WebsiteCardChrome({
  website,
  hasLiveFeed,
  articleCount,
  latestHeadline,
  footer,
  outletProfile,
}: WebsiteCardChromeProps): ReactElement {
  const brand = website.primary_color || DEFAULT_BRAND_COLOR;
  const { inkClass, needsRing } = tileTreatment(brand);
  return (
    <div className="flex h-full flex-col overflow-hidden rounded-lg border border-cog-divider bg-cog-surface shadow-cog-e1">
      <div className="flex flex-1 flex-col gap-cog-3 p-cog-4">
        <div className="flex items-start gap-cog-3">
          {/* Brand avatar chip — decorative (name is the accessible label). */}
          <span
            aria-hidden="true"
            className={[
              "flex size-cog-7-5 shrink-0 items-center justify-center rounded-md text-heading-sm font-bold",
              inkClass,
              needsRing ? "border border-cog-divider" : "",
            ]
              .filter(Boolean)
              .join(" ")}
            style={{ backgroundColor: brand }}
          >
            {monogram(website.name)}
          </span>
          <div className="min-w-cog-0 flex-1">
            <p className="font-serif-masthead text-heading-lg font-bold leading-tight text-cog-text-primary">
              {website.name}
            </p>
            <p
              dir="ltr"
              className="truncate font-mono text-caption text-cog-text-tertiary text-start"
            >
              {rangeDomain(website.domain_slug)}
            </p>
          </div>
        </div>

        <div className="flex flex-wrap items-center gap-cog-2">
          <LeanBadge lean={website.political_leaning} />
          {hasLiveFeed ? <RssLiveBadge /> : null}
          {outletProfile ? (
            <Link
              to={`/range/exercises/${outletProfile.exerciseId}/admin/profiles/${outletProfile.characterId}`}
              aria-label={m.range_baseline_card_outlet_profile_link({
                handle: outletProfile.username,
              })}
              className="inline-flex items-center gap-cog-1 rounded-pill border border-cog-blue-200 bg-cog-blue-50 px-cog-2 py-cog-0-5 text-micro font-semibold text-cog-blue-700 hover:bg-cog-blue-100 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-cog-focus dark:border-cog-blue-300 dark:bg-cog-blue-800 dark:text-cog-blue-100 dark:hover:bg-cog-blue-700"
            >
              <VerifiedBadge decorative />
              <span
                dir="ltr"
                style={{ unicodeBidi: "isolate" }}
                className="font-mono"
              >
                {m.range_profile_handle_prefix()}
                {outletProfile.username}
              </span>
            </Link>
          ) : null}
          <span className="text-caption text-cog-text-tertiary">
            {m.range_baseline_card_article_count({ count: articleCount })}
          </span>
        </div>

        {/* Latest-article mini-preview (serif headline). */}
        <div className="mt-auto border-t border-cog-divider pt-cog-3">
          <p className="text-eyebrow uppercase text-cog-text-eyebrow">
            {m.range_baseline_card_latest_label()}
          </p>
          {latestHeadline ? (
            <p className="mt-cog-1 line-clamp-2 font-serif-masthead text-body-md font-semibold text-cog-text-primary">
              {latestHeadline}
            </p>
          ) : (
            <p className="mt-cog-1 text-body-sm italic text-cog-text-tertiary">
              {m.range_baseline_card_no_articles()}
            </p>
          )}
        </div>
      </div>
      {footer ? (
        <div className="border-t border-cog-divider px-cog-4 py-cog-3">
          {footer}
        </div>
      ) : null}
    </div>
  );
}

// ─── Admin variant ────────────────────────────────────────────────────────────

export interface AdminWebsiteCardProps {
  readonly website: BaselineWebsite;
  /**
   * The exercise the admin is configuring — load-bearing for the outlet-profile
   * pill target (`/range/exercises/:exerciseId/admin/profiles/:characterId`).
   */
  readonly exerciseId: string;
  readonly hasLiveFeed: boolean;
  readonly articleCount: number;
  readonly latestHeadline?: string;
  /** Whether this website is enabled for the current exercise. */
  readonly enabled: boolean;
  readonly onToggleEnabled: (next: boolean) => void;
  readonly onSync?: () => void;
  readonly syncing?: boolean;
  /** Settings affordance (e.g. opens the edit modal). */
  readonly onSettings?: () => void;
  /**
   * The /range-prefixed link to the instructor Article Manager for this
   * website. When set, the footer carries the single "Manage articles" link.
   * (The admin card deliberately has no participant-reader link — routing an
   * instructor into the participant Newsstand is a surface leak.)
   */
  readonly manageTo?: string;
  /**
   * Task 9 (#2012): true blocks BOTH the enable toggle and Sync — both are
   * real execution RPCs (SetWebsiteEnabled / force-sync a live feed) against
   * an exercise that isn't `active`. "Manage articles" and Settings stay
   * open (navigation / authoring).
   */
  readonly executionGated?: boolean;
  readonly executionGatedReason?: string;
}

export function AdminWebsiteCard({
  website,
  exerciseId,
  hasLiveFeed,
  articleCount,
  latestHeadline,
  enabled,
  onToggleEnabled,
  onSync,
  syncing = false,
  onSettings,
  manageTo,
  executionGated = false,
  executionGatedReason,
}: AdminWebsiteCardProps): ReactElement {
  // Per-card ids: the grid renders many of these at once.
  const enableBlockedReasonId = `baseline-enable-blocked-reason-${website.id}`;
  const syncBlockedReasonId = `baseline-sync-blocked-reason-${website.id}`;
  const enableGate = useGatedAffordance(
    executionGated,
    executionGatedReason,
    enableBlockedReasonId,
  );
  const syncGate = useGatedAffordance(
    !syncing && executionGated,
    executionGatedReason,
    syncBlockedReasonId,
  );
  const outletProfile =
    website.officialProfileCharacterId && website.officialProfileUsername
      ? {
          exerciseId,
          characterId: website.officialProfileCharacterId,
          username: website.officialProfileUsername,
        }
      : undefined;
  const footer = (
    <div className="flex flex-wrap items-center justify-between gap-cog-2">
      <button
        type="button"
        role="switch"
        aria-checked={enabled}
        aria-label={m.range_baseline_card_enable_label({ name: website.name })}
        {...enableGate.props}
        onClick={enableGate.guard(() => onToggleEnabled(!enabled))}
        className={[
          "inline-flex min-h-btn-sm items-center gap-cog-2 rounded-md border px-cog-3 text-body-sm font-medium",
          "focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-cog-focus",
          executionGated
            ? "cursor-not-allowed border-cog-border bg-cog-surface-muted text-cog-text-tertiary"
            : enabled
              ? "border-cog-blue-600 bg-cog-blue-50 text-cog-blue-700 dark:border-cog-blue-300 dark:bg-cog-blue-800 dark:text-cog-blue-100"
              : "border-cog-border-emphasized bg-cog-surface text-cog-text-secondary hover:bg-cog-surface-muted",
        ].join(" ")}
      >
        <span
          aria-hidden="true"
          className={[
            "size-cog-2 rounded-pill",
            enabled
              ? "bg-cog-blue-600 dark:bg-cog-blue-300"
              : "bg-cog-border-emphasized",
          ].join(" ")}
        />
        {enabled
          ? m.range_baseline_card_enabled_on()
          : m.range_baseline_card_enabled_off()}
      </button>
      {enableGate.reasonNode}

      <div className="flex flex-wrap items-center gap-cog-1">
        {manageTo ? (
          <Link
            to={manageTo}
            className="inline-flex min-h-btn-sm items-center rounded-md border border-cog-border bg-cog-surface px-cog-3 text-body-sm font-medium text-cog-text-secondary hover:bg-cog-surface-muted focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-cog-focus"
          >
            {m.range_baseline_articles_manage_cta()}
          </Link>
        ) : null}
        {hasLiveFeed && onSync ? (
          <>
            <button
              type="button"
              onClick={syncGate.guard(onSync)}
              disabled={syncing}
              aria-busy={syncing}
              {...syncGate.props}
              className={
                !syncing && executionGated
                  ? "inline-flex min-h-btn-sm items-center rounded-md border border-cog-divider bg-cog-surface-muted px-cog-3 text-body-sm font-medium text-cog-text-tertiary cursor-not-allowed"
                  : "inline-flex min-h-btn-sm items-center rounded-md border border-cog-border bg-cog-surface px-cog-3 text-body-sm font-medium text-cog-text-secondary hover:bg-cog-surface-muted focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-cog-focus disabled:cursor-not-allowed disabled:border-cog-divider disabled:bg-cog-surface-muted disabled:text-cog-text-tertiary"
              }
            >
              {syncing
                ? m.range_baseline_card_syncing()
                : m.range_baseline_card_sync_cta()}
            </button>
            {syncGate.reasonNode}
          </>
        ) : null}
        {onSettings ? (
          <button
            type="button"
            onClick={onSettings}
            className="inline-flex min-h-btn-sm items-center rounded-md border border-cog-border bg-cog-surface px-cog-3 text-body-sm font-medium text-cog-text-secondary hover:bg-cog-surface-muted focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-cog-focus"
          >
            {m.range_baseline_card_settings_cta()}
          </button>
        ) : null}
      </div>
    </div>
  );

  return (
    <li className="list-none" data-testid="website-card">
      <WebsiteCardChrome
        website={website}
        hasLiveFeed={hasLiveFeed}
        articleCount={articleCount}
        latestHeadline={latestHeadline}
        footer={footer}
        outletProfile={outletProfile}
      />
    </li>
  );
}

// ─── Participant variant ───────────────────────────────────────────────────────

export interface ParticipantWebsiteCardProps {
  readonly website: BaselineWebsite;
  readonly hasLiveFeed: boolean;
  readonly articleCount: number;
  readonly latestHeadline?: string;
  /** The /range-prefixed link to this publication's article list. */
  readonly to: string;
}

export function ParticipantWebsiteCard({
  website,
  hasLiveFeed,
  articleCount,
  latestHeadline,
  to,
}: ParticipantWebsiteCardProps): ReactElement {
  return (
    <li className="list-none" data-testid="website-card">
      <Link
        to={to}
        className="block h-full rounded-lg focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-cog-focus"
      >
        <WebsiteCardChrome
          website={website}
          hasLiveFeed={hasLiveFeed}
          articleCount={articleCount}
          latestHeadline={latestHeadline}
        />
      </Link>
    </li>
  );
}


