/**
 * WebsiteCreateModal — the New-website dialog (Epic #266, #336).
 *
 * Two-column dialog: Manual form (left) + a live BaselineMasthead /
 * BrowserChromeFrame preview (right). AI-assisted / Import / Hybrid modes are
 * deferred → disabled "Soon" chips. Built incrementally against the
 * test-writer's failing tests; this commit lands the dialog shell + the
 * publication-name field with focus-on-open.
 *
 * Built on @omnicore-platform/ui Dialog (Radix). Dialog.Content owns
 * portalling (the panel mounts at the document root as a fixed overlay — it
 * never sits inline pushing the roster down), the focus trap, focus restore,
 * scroll lock, Esc-to-close, and scrim-click dismissal; Root's onOpenChange
 * routes every dismissal to onClose and vetoes it mid-submit. The dialog's
 * accessible name is sourced by Radix from Dialog.Title; focus moves to the
 * name field on open via onOpenAutoFocus (modal a11y, design.md §1 modal).
 */

import { type ReactElement, useId, useRef, useState } from "react";
import { Dialog, RadioGroup } from "@omnicore-platform/ui";
import { Check, X } from "@omnicore-platform/ui/icons";
import { useToast } from "@omnicore-platform/platform-chrome/toast";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";
import { rangeDomain } from "../../lib/rangeDomain";
import { BaselineMasthead } from "./BaselineMasthead";
import { BrowserChromeFrame } from "./BrowserChromeFrame";
import {
  BASELINE_BRAND_PALETTE,
  DEFAULT_BRAND_COLOR,
} from "../../constants/baselineBrandPalette";
import {
  createWebsite,
  setWebsiteEnabled,
  updateWebsite,
  type BaselineWebsite,
  type PoliticalLeaning,
} from "../../api/baseline";
import { LEANS, leanLabel } from "./LeanBadge";

export interface WebsiteCreateModalProps {
  /**
   * The exercise this dialog operates within. On CREATE the new website is
   * enabled for this exercise (SetWebsiteEnabled) right after it's added to the
   * org catalog — otherwise it would live in the catalog but never appear in the
   * exercise roster, which reads the per-exercise config rows.
   */
  readonly exerciseId: string;
  /** Close the dialog (Cancel / Esc / backdrop / post-create). */
  readonly onClose: () => void;
  /** Called after a successful create/save so the caller can refetch the list. */
  readonly onCreated: () => void;
  /**
   * When present, the dialog opens in EDIT mode: fields prefill from this
   * website, the title/submit reflect editing, and submit PATCHes via
   * UpdateWebsite instead of POSTing a new website.
   */
  readonly website?: BaselineWebsite;
}

export function WebsiteCreateModal({
  exerciseId,
  onClose,
  onCreated,
  website,
}: WebsiteCreateModalProps): ReactElement {
  const isEdit = website !== undefined;
  const nameRef = useRef<HTMLInputElement>(null);
  const [name, setName] = useState(website?.name ?? "");
  // Domain auto-suggests from the name until the user edits it directly; after
  // that the manual value sticks (domainDirty). In edit mode the existing
  // domain is the starting value and is treated as already-dirty (don't
  // re-derive it from the name).
  const [domain, setDomain] = useState(website?.domain_slug ?? "");
  const [domainDirty, setDomainDirty] = useState(isEdit);
  const [tagline, setTagline] = useState(website?.tagline ?? "");
  const [lean, setLean] = useState<PoliticalLeaning>(
    website?.political_leaning ?? "",
  );
  const [brandColor, setBrandColor] = useState(
    website?.primary_color || DEFAULT_BRAND_COLOR,
  );
  const [sections, setSections] = useState<readonly string[]>(
    website?.sections ?? [],
  );
  // Content source: "authored" is the default (no feed — articles are written
  // by hand in the Article Manager); "rss" reveals the RSS-URL field + creates
  // a Live feed. AI-generated "synthetic" + "hybrid" are deferred ("Soon").
  const [source, setSource] = useState<"authored" | "rss">("authored");
  const [feedUrl, setFeedUrl] = useState("");
  const [submitting, setSubmitting] = useState(false);
  const toast = useToast();

  const effectiveDomain = domainDirty ? domain : suggestDomain(name);

  async function handleCreate(): Promise<void> {
    setSubmitting(true);
    try {
      if (website !== undefined) {
        // Edit mode: PATCH the existing website. The content source / RSS URL
        // belong to feed provisioning (create-only), so edit covers the
        // editorial identity fields only. Edit never re-enables for the
        // exercise — the website is already part of the roster.
        await updateWebsite(website.id, {
          name,
          domain_slug: effectiveDomain,
          tagline,
          primary_color: brandColor,
          ...(lean !== "" ? { political_leaning: lean } : {}),
          sections,
        });
      } else {
        // Create mode: add the website to the org catalog, then enable it for
        // this exercise. CreateWebsite has no exercise binding, so without the
        // SetWebsiteEnabled step the new site would never appear in the
        // exercise roster (which reads the per-exercise config rows).
        const { website: created } = await createWebsite({
          name,
          domain_slug: effectiveDomain,
          tagline,
          primary_color: brandColor,
          ...(lean !== "" ? { political_leaning: lean } : {}),
          ...(sections.length > 0 ? { sections } : {}),
          // Authored source creates no live feed → omit feed_url. Live RSS
          // sends the entered URL so the upstream provisions the feed + sync.
          ...(source === "rss" && feedUrl ? { feed_url: feedUrl } : {}),
        });
        await setWebsiteEnabled(exerciseId, created.id, { is_enabled: true });
        // Success feedback is create-only — edit's confirmation is simply the
        // dialog closing on the already-visible roster entry.
        toast.success(m.range_baseline_modal_create_success());
      }
      onCreated();
      onClose();
    } catch {
      // Surface the failure (never silently close); the dialog stays open so
      // the user sees the toast and can retry / cancel. A danger toast
      // (role="alert") from the shared toast host — not an inline element —
      // so it fires from inside this Radix modal without pointer-events
      // fighting the scrim (see toast.tsx's pointerEvents:"auto" viewport).
      toast.danger(m.range_baseline_modal_error());
    } finally {
      setSubmitting(false);
    }
  }

  return (
    // Mounted === open. Radix-driven dismissals (Esc, scrim click) route here;
    // veto them mid-submit, otherwise forward to onClose.
    <Dialog.Root
      open
      onOpenChange={(open) => {
        if (!open && !submitting) onClose();
      }}
    >
      <Dialog.Content
        // Radix would focus the panel itself; redirect the initial focus to
        // the publication-name field (modal a11y, design.md §1 modal).
        onOpenAutoFocus={(e) => {
          e.preventDefault();
          nameRef.current?.focus();
        }}
        // Wider than the default modal width — the form is two-column with a
        // live preview. Capped to the viewport with internal scroll so a tall
        // form never overflows off-screen.
        className="max-h-cog-vh-inset-96 w-full max-w-cog-modal-w-clamped overflow-y-auto p-cog-6"
      >
        <Dialog.Title asChild>
          <h2 className="font-serif-masthead text-heading-lg font-bold text-cog-text-primary">
            {isEdit
              ? m.range_baseline_modal_edit_title()
              : m.range_baseline_modal_title()}
          </h2>
        </Dialog.Title>

      <ModeChips />

      <div className="mt-cog-4 grid grid-cols-1 gap-cog-5 md:grid-cols-2">
        <div className="flex flex-col gap-cog-4">
        <Field label={m.range_baseline_modal_field_name()}>
          {(id) => (
            <input
              id={id}
              ref={nameRef}
              type="text"
              value={name}
              onChange={(e) => setName(e.target.value)}
              placeholder={m.range_baseline_modal_field_name_placeholder()}
              className={INPUT_CLS}
            />
          )}
        </Field>

        <Field
          label={m.range_baseline_modal_field_domain()}
          hint={m.range_baseline_modal_field_domain_hint()}
        >
          {(id) => (
            <div className="flex items-stretch">
              <input
                id={id}
                type="text"
                dir="ltr"
                value={effectiveDomain}
                onChange={(e) => {
                  setDomainDirty(true);
                  setDomain(e.target.value);
                }}
                className={`${INPUT_CLS} font-mono flex-1 rounded-e-none`}
              />
              <span
                aria-hidden="true"
                className="inline-flex items-center rounded-e-md border border-s-0 border-cog-border bg-cog-surface-muted px-cog-3 font-mono text-body-sm text-cog-text-tertiary"
              >
                .range
              </span>
            </div>
          )}
        </Field>

        <Field
          label={m.range_baseline_modal_field_tagline()}
          hint={m.range_baseline_modal_field_tagline_counter({
            count: tagline.length,
          })}
        >
          {(id) => (
            <input
              id={id}
              type="text"
              value={tagline}
              maxLength={120}
              onChange={(e) => setTagline(e.target.value)}
              className={INPUT_CLS}
            />
          )}
        </Field>

        <LeanChips lean={lean} onLeanChange={setLean} />

        <BrandColorPicker value={brandColor} onChange={setBrandColor} />

        <SectionsTokenizer sections={sections} onChange={setSections} />

        {/* Content source + RSS URL drive feed provisioning, which is
            create-only — editing an existing website never re-provisions. */}
        {!isEdit ? (
          <ContentSource source={source} onSourceChange={setSource} />
        ) : null}

        {!isEdit && source === "rss" ? (
          <Field
            label={m.range_baseline_modal_field_rss_url()}
          >
            {(id) => (
              <input
                id={id}
                type="text"
                dir="ltr"
                value={feedUrl}
                onChange={(e) => setFeedUrl(e.target.value)}
                placeholder={m.range_baseline_modal_field_rss_url_placeholder()}
                className={`${INPUT_CLS} font-mono`}
              />
            )}
          </Field>
        ) : null}
        </div>

        {/* Sticky live preview — pure presentation, re-renders on every field
            change. The masthead name renders as serif display text (not an
            input), so it's distinct from the name field's value. */}
        <div className="md:sticky md:top-cog-4 md:self-start">
          <BrowserChromeFrame domain={effectiveDomain ? rangeDomain(effectiveDomain) : "example.range"}>
            <BaselineMasthead
              name={name || m.range_baseline_modal_field_name_placeholder()}
              brandColor={brandColor}
              tagline={tagline}
            />
          </BrowserChromeFrame>
        </div>
      </div>

      <div className="mt-cog-5 flex items-center justify-between gap-cog-3 border-t border-cog-divider pt-cog-4">
        <p
          role="status"
          className="text-caption text-cog-text-tertiary"
        >
          {readinessSummary(name, effectiveDomain, source)}
        </p>
        <div className="flex items-center gap-cog-2">
        <button
          type="button"
          onClick={onClose}
          className="inline-flex min-h-btn items-center rounded-md border border-cog-border bg-cog-surface px-cog-4 text-body-sm font-medium text-cog-text-secondary hover:bg-cog-surface-muted focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-cog-focus"
        >
          {m.range_baseline_modal_cancel()}
        </button>
        <button
          type="button"
          onClick={() => void handleCreate()}
          disabled={submitting}
          aria-busy={submitting}
          className="inline-flex min-h-btn items-center rounded-md bg-cog-blue-600 px-cog-4 text-body-sm font-semibold text-white hover:bg-cog-blue-700 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-cog-focus disabled:cursor-not-allowed disabled:bg-cog-surface-muted disabled:text-cog-text-tertiary dark:bg-cog-blue-700 dark:hover:bg-cog-blue-800"
        >
          {isEdit
            ? submitting
              ? m.range_baseline_modal_saving()
              : m.range_baseline_modal_save()
            : submitting
              ? m.range_baseline_modal_submitting()
              : m.range_baseline_modal_submit()}
        </button>
        </div>
      </div>
      </Dialog.Content>
    </Dialog.Root>
  );
}

/**
 * readinessSummary — the footer status line. Name AND domain are required;
 * until both are present the summary states what's needed. Once ready, the
 * summary reflects the selected content source (Authored vs Live RSS).
 */
function readinessSummary(
  name: string,
  domain: string,
  source: "authored" | "rss",
): string {
  if (name.trim() === "" || domain.trim() === "") {
    return m.range_baseline_modal_ready_required();
  }
  return source === "rss"
    ? m.range_baseline_modal_ready_rss()
    : m.range_baseline_modal_ready_authored();
}

/**
 * LeanChips — the editorial-lean selector. One chip per lean (icon-dot
 * decorative + label text; the LABEL carries the meaning, never color or
 * position alone — design §8 RTL note). Selecting a chip sets the
 * political_leaning that flows into the Create POST. aria-pressed marks the
 * selected chip; the group is labeled for SR users.
 */
function LeanChips({
  lean,
  onLeanChange,
}: {
  lean: PoliticalLeaning;
  onLeanChange: (next: PoliticalLeaning) => void;
}): ReactElement {
  return (
    <fieldset className="flex flex-col gap-cog-1">
      <legend className="text-caption font-medium text-cog-text-secondary">
        {m.range_baseline_modal_field_lean()}
      </legend>
      <div className="flex flex-wrap gap-cog-2" role="group">
        {LEANS.map((value) => {
          const selected = lean === value;
          return (
            <button
              key={value}
              type="button"
              aria-pressed={selected}
              onClick={() => onLeanChange(value)}
              className={[
                "inline-flex min-h-btn-sm items-center gap-cog-1 rounded-pill border px-cog-3 text-body-sm font-medium",
                "focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-cog-focus",
                selected
                  ? "border-cog-blue-600 bg-cog-blue-50 text-cog-blue-700 dark:border-cog-blue-300 dark:bg-cog-blue-800 dark:text-cog-blue-100"
                  : "border-cog-border bg-cog-surface text-cog-text-secondary hover:bg-cog-surface-muted",
              ].join(" ")}
            >
              <span
                aria-hidden="true"
                className="size-cog-1-5 rounded-pill bg-current"
              />
              {leanLabel(value)}
            </button>
          );
        })}
      </div>
    </fieldset>
  );
}

/**
 * SectionsTokenizer — the nav-section tokenizer. Type a section name and press
 * Enter to add it as a chip; each chip has a remove control. The chip list is
 * the sections[] that flows into the Create POST (order preserved). Duplicates
 * and blanks are ignored. Labeled input + describedby hint (design.md inputs).
 */
function SectionsTokenizer({
  sections,
  onChange,
}: {
  sections: readonly string[];
  onChange: (next: readonly string[]) => void;
}): ReactElement {
  const inputId = useId();
  const hintId = useId();
  const [draft, setDraft] = useState("");

  function commit(): void {
    const value = draft.trim();
    if (value === "" || sections.includes(value)) {
      setDraft("");
      return;
    }
    onChange([...sections, value]);
    setDraft("");
  }

  return (
    <div className="flex flex-col gap-cog-1">
      <label
        htmlFor={inputId}
        className="text-caption font-medium text-cog-text-secondary"
      >
        {m.range_baseline_modal_field_sections()}
      </label>
      {sections.length > 0 ? (
        <ul className="flex flex-wrap gap-cog-2">
          {sections.map((section) => (
            <li
              key={section}
              className="inline-flex items-center gap-cog-1 rounded-pill border border-cog-border bg-cog-surface-muted px-cog-2 py-cog-0-5 text-body-sm text-cog-text-secondary"
            >
              {section}
              <button
                type="button"
                aria-label={m.range_baseline_modal_section_remove_label({
                  name: section,
                })}
                onClick={() => onChange(sections.filter((s) => s !== section))}
                // WCAG 2.5.8: the button is the hit target and grows to the
                // named tap rung; the drawn glyph moves to an inner span
                // (size-cog-4, unchanged) so it never visually enlarges.
                className="inline-flex min-h-tap min-w-tap items-center justify-center rounded-pill text-cog-text-tertiary hover:text-cog-text-primary focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-1 focus-visible:outline-cog-focus"
              >
                <span aria-hidden="true" className="inline-flex size-cog-4 items-center justify-center">
                  <X aria-hidden="true" className="h-cog-3 w-cog-3" />
                </span>
              </button>
            </li>
          ))}
        </ul>
      ) : null}
      <input
        id={inputId}
        type="text"
        value={draft}
        aria-describedby={hintId}
        onChange={(e) => setDraft(e.target.value)}
        onKeyDown={(e) => {
          if (e.key === "Enter") {
            e.preventDefault();
            commit();
          }
        }}
        className={INPUT_CLS}
      />
      <span id={hintId} className="text-caption text-cog-text-tertiary">
        {m.range_baseline_modal_field_sections_hint()}
      </span>
    </div>
  );
}

/**
 * BrandColorPicker — the curated brand-color swatch radiogroup. One radio per
 * BASELINE_BRAND_PALETTE entry; the accessible name pairs the localized color
 * NAME with the swatch (color is never communicated by fill alone — design
 * §1.4 / a11y). Selecting sets primary_color (the hex) which flows into the
 * Create POST and recolors the live preview masthead.
 */
function BrandColorPicker({
  value,
  onChange,
}: {
  value: string;
  onChange: (hex: string) => void;
}): ReactElement {
  return (
    <fieldset className="flex flex-col gap-cog-1">
      <legend className="text-caption font-medium text-cog-text-secondary">
        {m.range_baseline_modal_field_brand_color()}
      </legend>
      <RadioGroup.Root
        value={value}
        onValueChange={onChange}
        className="flex flex-wrap gap-cog-2"
      >
        {BASELINE_BRAND_PALETTE.map((entry) => {
          const label = m.range_baseline_modal_brand_swatch_label({
            color: entry.label(),
          });
          const selected = value === entry.hex;
          return (
            <RadioGroup.Item
              key={entry.hex}
              value={entry.hex}
              aria-label={label}
              className="flex size-cog-6 items-center justify-center rounded-pill focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-cog-blue-600 data-[state=checked]:ring-2 data-[state=checked]:ring-cog-text-primary data-[state=checked]:ring-offset-2"
              style={{ backgroundColor: entry.hex }}
            >
              {selected ? (
                <Check aria-hidden="true" className="h-cog-3-5 w-cog-3-5 text-white" />
              ) : null}
            </RadioGroup.Item>
          );
        })}
      </RadioGroup.Root>
    </fieldset>
  );
}

/**
 * ContentSource — the content-source radiogroup. Two WORKING radios first:
 * Authored is the default (no feed — articles are written by hand in the
 * Article Manager) and Live RSS reveals the RSS-URL field + provisions a feed.
 * Then two deferred SOON chips: Synthetic (AI-generated articles — no backend
 * yet) and Hybrid (disabled "Soon", focusable, distinct bg+border, Soon pill —
 * same treatment as the mode chips). Meaning is carried by the label, never
 * position/color alone.
 */
function ContentSource({
  source,
  onSourceChange,
}: {
  source: "authored" | "rss";
  onSourceChange: (next: "authored" | "rss") => void;
}): ReactElement {
  const authoredId = useId();
  const rssId = useId();
  return (
    <fieldset className="flex flex-col gap-cog-1">
      <legend className="text-caption font-medium text-cog-text-secondary">
        {m.range_baseline_modal_field_source()}
      </legend>
      <RadioGroup.Root
        value={source}
        onValueChange={(v) => onSourceChange(v as "authored" | "rss")}
        className="flex flex-wrap gap-cog-3"
      >
        <div className="inline-flex items-center gap-cog-2">
          <RadioGroup.Item id={authoredId} value="authored" />
          <label
            htmlFor={authoredId}
            className="text-body-sm text-cog-text-primary"
          >
            {m.range_baseline_modal_source_authored()}
          </label>
        </div>
        <div className="inline-flex items-center gap-cog-2">
          <RadioGroup.Item id={rssId} value="rss" />
          <label htmlFor={rssId} className="text-body-sm text-cog-text-primary">
            {m.range_baseline_modal_source_rss()}
          </label>
        </div>
        <SoonChip label={m.range_baseline_modal_source_synthetic()} />
        <SoonChip label={m.range_baseline_modal_source_hybrid()} />
      </RadioGroup.Root>
    </fieldset>
  );
}

/**
 * ModeChips — the three creation modes. Manual is the active/selected mode (the
 * only in-scope one); AI-assisted and Import are deferred → rendered as
 * disabled "Soon" chips: real <button aria-disabled>, kept focusable (never
 * removed from the tab order), distinct bg+border (not opacity-only), with a
 * visible "Soon" pill so the deferral is discoverable by keyboard/SR users and
 * never communicated by styling alone (design.md §0/§8.3, mirrors the
 * ExerciseShell disabled-nav pattern).
 */
function ModeChips(): ReactElement {
  return (
    <div className="mt-cog-3 flex flex-wrap gap-cog-2" role="group">
      <button
        type="button"
        aria-pressed="true"
        className="inline-flex min-h-btn-sm items-center rounded-md border border-cog-blue-600 bg-cog-blue-50 px-cog-3 text-body-sm font-semibold text-cog-blue-700 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-cog-focus dark:border-cog-blue-300 dark:bg-cog-blue-800 dark:text-cog-blue-100"
      >
        {m.range_baseline_modal_mode_manual()}
      </button>
      <SoonChip label={m.range_baseline_modal_mode_ai()} />
      <SoonChip label={m.range_baseline_modal_mode_import()} />
    </div>
  );
}

/** A deferred mode chip — disabled but focusable, with a "Soon" pill. */
function SoonChip({ label }: { label: string }): ReactElement {
  return (
    <button
      type="button"
      aria-disabled="true"
      tabIndex={0}
      aria-label={m.range_baseline_admin_soon_label({ feature: label })}
      className="inline-flex min-h-btn-sm cursor-not-allowed select-none items-center gap-cog-2 rounded-md border border-cog-border bg-cog-surface-muted px-cog-3 text-body-sm font-medium text-cog-text-tertiary focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-cog-focus"
    >
      {label}
      <span className="inline-flex items-center rounded-pill border border-cog-border bg-cog-surface-muted px-cog-2 py-cog-0-5 text-micro font-semibold uppercase text-cog-text-tertiary">
        {m.range_baseline_admin_soon_pill()}
      </span>
    </button>
  );
}

/** Shared input class — single source for the modal's text fields. */
const INPUT_CLS =
  "min-h-input rounded-md border border-cog-border bg-cog-surface px-cog-3 text-body-sm text-cog-text-primary placeholder:text-cog-text-tertiary focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-cog-focus";

/**
 * Field — a labeled input wrapper with a real <label htmlFor> association and
 * an optional hint. The child render-prop receives the generated id so the
 * input binds to the label (design.md inputs invariant: real label, never a
 * placeholder-as-label).
 */
function Field({
  label,
  hint,
  children,
}: {
  label: string;
  hint?: string;
  children: (id: string) => ReactElement;
}): ReactElement {
  const id = useId();
  return (
    <div className="flex flex-col gap-cog-1">
      <label htmlFor={id} className="text-caption font-medium text-cog-text-secondary">
        {label}
      </label>
      {children(id)}
      {hint !== undefined ? (
        <span className="text-caption text-cog-text-tertiary">{hint}</span>
      ) : null}
    </div>
  );
}

/**
 * suggestDomain — derive a plausible domain slug from the publication name:
 * lowercase, strip non-alphanumerics to nothing. Returns the bare slug with NO
 * TLD suffix — the `.range` adornment is rendered separately in the UI, and
 * the stored `domain_slug` field is always the bare value (e.g. "msnbc", not
 * "msnbc.range" or "msnbc.news"). Empty name → empty suggestion.
 */
export function suggestDomain(name: string): string {
  const slug = name
    .toLowerCase()
    .replace(/[^a-z0-9-]+/g, "")
    .replace(/-+/g, "-")
    .replace(/^-|-$/g, "")
    .trim();
  return slug;
}

export default WebsiteCreateModal;


